205	/// Turn phases.
206	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
207	pub enum Phase {
208	    Beginning,
209	    PrecombatMain,
210	    Combat,
211	    PostcombatMain,
212	    Ending,
213	}
