345	/// A declarative continuous effect on a card. The engine reads these
346	/// instead of parsing oracle text strings.
347	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
348	pub enum ContinuousEffect {
349	    /// Modify power and/or toughness.
350	    ModifyPT { power: i32, toughness: i32, scope: EffectScope },
351	    /// Grant a keyword ability.
352	    GrantKeyword { keyword: Keyword, scope: EffectScope },
353	    /// Creature can't attack.
354	    PreventAttack { scope: EffectScope },
355	    /// Creature can't block.
356	    PreventBlock { scope: EffectScope },
357	    /// Creature can't be blocked.
358	    CantBeBlocked { scope: EffectScope },
359	    /// Creature can only be blocked by creatures matching the filter.
360	    /// Used for Orchard Spirit (flying/reach), Skulk (power < N), Shadow, Fear, etc.
361	    BlockRestriction { allowed_blockers: CreatureFilter, scope: EffectScope },
362	    /// Prevent all combat damage dealt to and by creature.
363	    PreventCombatDamage { scope: EffectScope },
364	    /// Creature doesn't untap during controller's untap step.
365	    PreventUntap { scope: EffectScope },
366	    /// Creature attacks each combat if able.
367	    ForceAttack { scope: EffectScope },
368	    /// Protection from a subtype (prevents damage, blocking, targeting, enchanting).
369	    ProtectionFromSubtype { subtype: String, scope: EffectScope },
370	    /// Protection from creatures matching a filter.
371	    ProtectionFrom { filter: CreatureFilter, scope: EffectScope },
372	    /// Conditional keyword: granted only when a condition is met.
373	    ConditionalKeyword { keyword: Keyword, condition: EffectCondition, scope: EffectScope },
374	    /// Reduce cost of spells matching a filter.
375	    ReduceCost { reduction: u32, filter: SpellFilter },
376	    /// Creature can't be blocked except by N or more creatures.
377	    /// Used for "can't be blocked except by two or more creatures" (Terror of Kruin Pass).
378	    MinimumBlockers { count: u32, scope: EffectScope },
379	    /// If this creature would be dealt damage, prevent that damage and remove a +1/+1 counter.
380	    /// Used by Unbreathing Horde.
381	    PreventDamageRemoveCounter { scope: EffectScope },
382	    /// Double combat damage dealt by and to this creature.
383	    /// Used by Inquisitor's Flail.
384	    DoubleCombatDamage { scope: EffectScope },
385	}
